FontWeight.Semibold

UpdateIf(
    colProjectRevenueContracts,
    'Project Revenue' = gal_ProjectRevenues_DisplayProjectBodyRightContent_GridContracts_1.Selected.'Project Revenue',
    {  
        IsFolded: Not(gal_ProjectRevenues_DisplayProjectBodyRightContent_GridContracts_1.Selected.IsFolded)
    }
