If( 
    locSelectedRevenueContract.'Project Revenue' <> ThisItem.'Project Revenue',
    UpdateContext({ 
        locSelectedRevenueContract: ThisItem
    })
);

UpdateIf(
    colProjectRevenueContracts,
    'Project Revenue' = gal_ProjectRevenues_DisplayProjectBodyRightContent_GridContracts_1.Selected.'Project Revenue',
    {  
        IsFolded: Not(gal_ProjectRevenues_DisplayProjectBodyRightContent_GridContracts_1.Selected.IsFolded)
    }
);

If( 
    locSelectedRevenueContract.'Project Revenue' <> ThisItem.'Project Revenue',
    UpdateContext({ 
        locSelectedRevenueContract: ThisItem
    })
);

Table(
    {
        ItemKey: "editRevenueContract",
        ItemDisplayName: "Edit",
        ItemIconName: "Edit",
        ItemEnabled: RecordInfo(
            LookUp(
                'Project Revenues',
                'Project Revenue' = locSelectedRevenueContract.'Project Revenue'
            ),
            RecordInfo.EditPermission
        )
    },
    {
        ItemKey: "deleteRevenueContract",
        ItemDisplayName: "Delete",
        ItemIconName: "Delete",
        ItemEnabled: RecordInfo(
            LookUp(
                'Project Revenues',
                'Project Revenue' = locSelectedRevenueContract.'Project Revenue'
            ),
            RecordInfo.DeletePermission
        )
    }
)

UpdateContext(
    {
        locSelectedRevenueContract: ThisItem,
        locRevenueContractFormDirty: false
    }
);
Switch(
    Self.Selected.ItemKey,
    "editRevenueContract",
    With(
        {varSelectedRevenueContract: locSelectedRevenueContract},
        UpdateContext({locSelectedRevenueContract: Blank()});
        UpdateContext(
            {
                locSelectedRevenueContract: varSelectedRevenueContract,
                locMode: "Edit",
                locIsVisibleRightPanelNewEditRevenueContract: true,
                locDateCOD: varSelectedRevenueContract.'Contract Start Date',
                locCountryRelatedAssumptions: If(
                    gblRecordSelectedProject.Country.Name = "Italy" && !IsBlank(locAreaWithRegion),
                    Filter(
                        'Assumptions Revenues SQL',
                        Or(
                            country = "Italy",
                            country = locAreaWithRegion
                        )
                    ),
                    Filter(
                        'Assumptions Revenues SQL',
                        country = gblRecordSelectedProject.Country.Name
                    )
                )
            }
        )
    );
    Concurrent(
        UpdateContext(
            {
                locRevenueContractEndDate: {
                    IsStandardAssumption: false,
                    Value: locSelectedRevenueContract.'Contract End Date',
                    StandardAssumptionValue: locSelectedRevenueContract.'Contract End Date'
                }
            }
        ),
        With(
            {
                _ProjectRelatedEnergyYield: !IsEmpty(
                    Filter(
                        'Energy Yields',
                        And(
                            Project.Project = gblRecordSelectedProject.Project,
                            'Consider Negative Prices' = 'Consider Negative Prices (Energy Yields)'.Yes,
                            Status = 'Status (Energy Yields)'.Active
                        )
                    )
                ),
                _NegativePriceAssumption: Filter(
                    locCountryRelatedAssumptions,
                    And(
                        valuetype in [
                            "consider_negtive_prices_active",
                            "initial_state_toggle",
                            "standard_sync"
                        ]
                    )
                ),
                _RevenueTypeText: Switch(
                    locSelectedRevenueContract.Label,
                    'Revenue Labels'.FiT,
                    "FiT",
                    'Revenue Labels'.PPA,
                    "PPA"
                )
            },
            With(
                {
                    _StandardSyncRecord: LookUp(
                        _NegativePriceAssumption,
                        category = _RevenueTypeText && valuetype = "standard_sync"
                    ),
                    _DisplayModeRecord: LookUp(
                        _NegativePriceAssumption,
                        category = _RevenueTypeText && valuetype = "consider_negtive_prices_active"
                    ),
                    _InitialStateRecord: LookUp(
                        _NegativePriceAssumption,
                        category = _RevenueTypeText && valuetype = "initial_state_toggle"
                    )
                },
                With(
                    {
                        _StandardSync: Switch(
                            gblRecordSelectedProject.Technology,
                            Technology.Wind,
                            _StandardSyncRecord.wind = "true",
                            Technology.PV,
                            _StandardSyncRecord.pv = "true",
                            false
                        ),
                        _NegativePriceDisplayMode: And(
                            Switch(
                                gblRecordSelectedProject.Technology,
                                Technology.Wind,
                                _DisplayModeRecord.wind = "true",
                                Technology.PV,
                                _DisplayModeRecord.pv = "true",
                                false
                            ),
                            _ProjectRelatedEnergyYield
                        ),
                        _InitialState: Switch(
                            gblRecordSelectedProject.Technology,
                            Technology.Wind,
                            _InitialStateRecord.wind = "On",
                            Technology.PV,
                            _InitialStateRecord.pv = "On",
                            false
                        )
                    },
                    UpdateContext(
                        {
                            locRevenueContractConsiderNegativePrice: {
                                DisplayMode: If(
                                    _NegativePriceDisplayMode,
                                    DisplayMode.Edit,
                                    DisplayMode.Disabled
                                ),
                                ToggleState: locSelectedRevenueContract.'Consider Negative Prices' = 'Consider Negative Prices (Project Revenues)'.Yes,
                                ManualOverride: locSelectedRevenueContract.NegativePriceManualOverride = 'NegativePriceManualOverride (Project Revenues)'.Yes
                            }
                        }
                    )
                )
            )
        ),
        UpdateContext(
            {
                locRevenueCorrectionFactorP50: {
                    Value: locSelectedRevenueContract.'Correction Factor',
                    IsStandardAssumption: If(
                        locSelectedRevenueContract.'Is Correction Factor Standard Assumption' = 'Is Correction Factor Standard Assumption (Project Revenues)'.Yes,
                        true,
                        false
                    ),
                    StandardAssumptionValue: 1
                }
            }
        ),
        UpdateContext(
            {
                locRevenueCorrectionFactorP90: {
                    Value: locSelectedRevenueContract.'Correction Factor p90',
                    IsStandardAssumption: If(
                        locSelectedRevenueContract.'Is Correction Factor P90 Standard Assumption' = 'Is Correction Factor P90 Standard Assumption (Project Revenues)'.Yes,
                        true,
                        false
                    ),
                    StandardAssumptionValue: 1
                }
            }
        ),
        UpdateContext(
            {
                locRevenueCurrency: {
                    Value: If(
                        Not(IsBlank(locSelectedRevenueContract.Currency)),
                        [locSelectedRevenueContract.Currency],
                        Switch(
                            gblRecordSelectedProject.Country.Name,
                        /*
                        Poland, LookUp(Currencies, 'Currency Code' = "PLN"),
                        Romania, LookUp(Currencies, 'Currency Code' = "RON"),
                        */
                            "",
                            LookUp(
                                Currencies,
                                'Currency Code' = "EUR"
                            ),
                            LookUp(
                                Currencies,
                                'Currency Code' = "EUR"
                            )
                        )
                    ),
                    IsStandardAssumption: true,
                    StandardAssumptionValue: If(
                        Not(IsBlank(locSelectedRevenueContract.Currency)),
                        [locSelectedRevenueContract.Currency],
                        Switch(
                            gblRecordSelectedProject.Country.Name,
                        /*
                        Poland, LookUp(Currencies, 'Currency Code' = "PLN"),
                        Romania, LookUp(Currencies, 'Currency Code' = "RON"),
                        */
                            "",
                            LookUp(
                                Currencies,
                                'Currency Code' = "EUR"
                            ),
                            LookUp(
                                Currencies,
                                'Currency Code' = "EUR"
                            )
                        )
                    )
                }
            }
        ),
        UpdateContext(
            {
                locRevenueContractStartDate: {
                    IsStandardAssumption: If(
                        locSelectedRevenueContract.'Is Contract Start Date Standard Assumption?' = 'Is Contract Start Date Standard Assumption? (Project Revenues)'.Yes,
                        true,
                        false
                    ),
                    Value: If(
                        Not(IsBlank(locSelectedRevenueContract.'Contract Start Date')),
                        DateAdd(
                            locSelectedRevenueContract.'Contract Start Date',
                            0,
                            TimeUnit.Days
                        ),
                        DateAdd(
                            Today(),
                            0,
                            TimeUnit.Days
                        )
                    ),
                    StandardAssumptionValue: DateAdd(
                        Today(),
                        0,
                        TimeUnit.Days
                    )
                }
            }
        ),
        UpdateContext(
            {
                locRevenueContractDurationInYears: {
                    IsStandardAssumption: If(
                        locSelectedRevenueContract.'Is Contract Duration Years Standard Assumption?' = 'Is Contract Duration Years Standard Assumption? (Project Revenues)'.Yes,
                        true,
                        false
                    ),
                    Value: Value(locSelectedRevenueContract.'Contract Duration Years'),
                    StandardAssumptionValue: 0
                }
            }
        ),
        UpdateContext(
            {
                locRevenueContractDurationInMonths: {
                    IsStandardAssumption: If(
                        locSelectedRevenueContract.'Is Contract Duration Months Standard Assumption?' = 'Is Contract Duration Months Standard Assumption? (Project Revenues)'.Yes,
                        true,
                        false
                    ),
                    Value: Value(locSelectedRevenueContract.'Contract Duration Months'),
                    StandardAssumptionValue: 0
                }
            }
        ),
        UpdateContext(
            {
                locRevenueInflationProfile: {
                    Value: If(
                        locSelectedRevenueContract.'Use Inflation Profile' = 'Use Inflation Profile (Project Revenues)'.Yes,
                        "true",
                        "false"
                    ),
                    StandardAssumptionValue: "false",
                    IsStandardAssumption: If(
                        locSelectedRevenueContract.'Is Use Inflation Profile Standard Assumption?' = 'Is Use Inflation Profile Standard Assumption? (Project Revenues)'.Yes,
                        true,
                        false
                    )
                }
            }
        ),
        UpdateContext(
            {
                locRevenueInflationCountryProfile: {
                    IsStandardAssumption: If(
                        locSelectedRevenueContract.'Is Use Custom Inflation Standard Assumption?' = 'Is Use Custom Inflation Standard Assumption? (Project Revenues)'.Yes,
                        true,
                        false
                    ),
                    StandardAssumptionValue: "false",
                    Value: If(
                        locSelectedRevenueContract.'Use Country Inflation Profile' = 'Use Country Inflation Profile (Project Revenues)'.Yes,
                        "true",
                        "false"
                    )
                }
            }
        ),
        UpdateContext(
            {
                locRevenueInflationCustomValue: {
                    IsStandardAssumption: If(
                        locSelectedRevenueContract.'Is Custom Inflation Profile Standard Assumption?' = 'Is Custom Inflation Profile Standard Assumption? (Project Revenues)'.Yes,
                        true,
                        false
                    ),
                    StandardAssumptionValue: Value(0),
                    Value: Value(locSelectedRevenueContract.'Inflation Profile')
                }
            }
        ),
        UpdateContext(
            {
                locRevenueInflationStartYear: {
                    IsStandardAssumption: If(
                        locSelectedRevenueContract.'Is Inflation Profile Year Standard Assumption?' = 'Is Inflation Profile Year Standard Assumption? (Project Revenues)'.Yes,
                        true,
                        false
                    ),
                    Value: Value(locSelectedRevenueContract.'Inflation Start Year'),
                    StandardAssumptionValue: Value(0)
                }
            }
        ),
        UpdateContext(
            {
                locRevenuePrice: {
                    IsStandardAssumption: Switch(
                        true,
                        And(
                            gblRecordSelectedProject.Country.Name = "Germany",
                            locSelectedRevenueContract.Label = 'Revenue Labels'.FiT,
                            gblRecordSelectedProject.Technology <> Technology.PV
                        ),
                        If(
                            locSelectedRevenueContract.'Is Bidding Price Standard Assumption?' = 'Is Bidding Price Standard Assumption? (Project Revenues)'.Yes,
                            true,
                            false
                        ),
                        If(
                            locSelectedRevenueContract.'Is Tarrif / Price Standard Assumption?' = 'Is Tarrif / Price Standard Assumption? (Project Revenues)'.Yes,
                            true,
                            false
                        )
                    ),
                    Value: If(
                        And(
                            gblRecordSelectedProject.Country.Name = "Germany",
                            locSelectedRevenueContract.Label = 'Revenue Labels'.FiT,
                            gblRecordSelectedProject.Technology <> Technology.PV
                        ),
                        Value(locSelectedRevenueContract.'Bidding Price'),
                        Value(locSelectedRevenueContract.'Tariff / Price')
                    ),
                    StandardAssumptionValue: Value(0)
                }
            }
        ),
        UpdateContext(
            {
                locRevenuePriceP90: {
                    IsStandardAssumption: Switch(
                        true,
                        And(
                            gblRecordSelectedProject.Country.Name = "Germany",
                            locSelectedRevenueContract.Label = 'Revenue Labels'.FiT,
                            gblRecordSelectedProject.Technology = Technology.Wind
                        ),
                        If(
                            locSelectedRevenueContract.'Is Tarrif / Price P90 Standard Assumption?' = 'Is Tarrif / Price P90 Standard Assumption? (Project Revenues)'.Yes,
                            true,
                            false
                        )
                    ),
                    Value: If(
                        And(
                            gblRecordSelectedProject.Country.Name = "Germany",
                            locSelectedRevenueContract.Label = 'Revenue Labels'.FiT,
                            gblRecordSelectedProject.Technology = Technology.Wind
                        ),
                        Value(locSelectedRevenueContract.'Tariff / Price')
                    ),
                    StandardAssumptionValue: Value(0)
                }
            }
        )
    );
    With(
        {
            recTarrifPrice: If(
                And(
                    gblRecordSelectedProject.Country.Name = "Germany",
                    drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Label_1.Selected.Value = 'Revenue Labels'.FiT,
                    gblRecordSelectedProject.Technology <> Technology.PV
                ),
                Text(
                    locRevenuePrice.Value * locRevenueCorrectionFactorP50.Value,
                    "0.00"
                ),
                Not(IsBlank(locSelectedRevenueContract)),
                Text(
                    Value(locRevenuePrice.Value),
                    "0.00"
                ),
                Text(
                    Value(locRevenuePrice.Value),
                    "0.00"
                )
            )
        },
        UpdateContext({locRevenuePriceActual: recTarrifPrice})
    );
    UpdateContext(
        {
            locStandardAssumtionContract: If(
                StartsWith(
                    Lower(locSelectedRevenueContract.Description),
                    "standard"
                ),
                true,
                false
            )
        }
    );
    UpdateContext(
        {
            locRevenueDescription: {
                IsStandardAssumption: locStandardAssumtionContract,
                Value: Text(locSelectedRevenueContract.Description),
                StandardAssumptionValue: Text("")
            }
        }
    );
    UpdateContext(
        {
            locRevenueContractHedgeType: {
                IsStandardAssumption: false,
                Value: Switch(
                    locSelectedRevenueContract.'Hedge Type',
                    'Hedging Type'.'Hedged Volume [%]',
                    'Hedging Type'.'Hedged Volume [%]',
                    'Hedging Type'.'Fixed Volume p.a. [MWh]',
                    'Hedging Type'.'Fixed Volume p.a. [MWh]',
                    'Hedging Type'.'Individual Volumes',
                    'Hedging Type'.'Individual Volumes'
                ),
                StandardAssumptionValue: Blank()
            }
        }
    );
    UpdateContext(
        {
            locRevenueContractHedgeVolumne: {
                IsStandardAssumption: If(
                    And(
                        locSelectedRevenueContract.'Is Hedged Volume Standard Assumption?' = 'Is Hedged Volume Standard Assumption? (Project Revenues)'.Yes,
                        locSelectedRevenueContract.'Hedge Type' = 'Hedging Type'.'Hedged Volume [%]'
                    ),
                    true,
                    false
                ),
                Value: If(
                    And(locSelectedRevenueContract.'Hedge Type' = 'Hedging Type'.'Hedged Volume [%]'),
                    Text(locSelectedRevenueContract.'Hedged Volume'),
                    Blank()
                ),
                StandardAssumptionValue: 0
            }
        }
    );
    UpdateContext(
        {
            locRevenueContractHedgeFixedValue: {
                IsStandardAssumption: false,
                Value: If(
                    And(locSelectedRevenueContract.'Hedge Type' = 'Hedging Type'.'Fixed Volume p.a. [MWh]'),
                    Value(locSelectedRevenueContract.FixedContractedmwhpa),
                    Blank()
                ),
                ValueText: If(
                    And(locSelectedRevenueContract.'Hedge Type' = 'Hedging Type'.'Fixed Volume p.a. [MWh]'),
                    Text(locSelectedRevenueContract.FixedContractedmwhpa),
                    Blank()
                ),
                StandardAssumptionValue: 0
            }
        }
    );
    UpdateContext(
        {
            locRevenueIsStandardAssumptions: {
                IsHedgedVolume: locRevenueContractHedgeVolumne.IsStandardAssumption,
                IsInflationValue: locRevenueInflationCustomValue.IsStandardAssumption,
                IsBiddingPrice: locRevenuePrice.IsStandardAssumption,
                IsCorrectionp50: locRevenueCorrectionFactorP50.IsStandardAssumption,
                IsCorrectionp90: locRevenueCorrectionFactorP90.IsStandardAssumption,
                IsInflationStartYear: locRevenueInflationStartYear.IsStandardAssumption
            },
            locRevenueStandardValues: {
                HedgedVolume: locRevenueContractHedgeVolumne.Value,
                InflationValue: locRevenueInflationCustomValue.Value,
                BiddingPrice: locRevenuePrice.Value,
                Correctionp50: locRevenueCorrectionFactorP50.Value,
                Correctionp90: locRevenueCorrectionFactorP90.Value,
                InflationStartYear: locRevenueInflationStartYear.Value
            }
        }
    );
    Clear(colRevenueHedgeIndividualVolume);
    If(
        locSelectedRevenueContract.'Hedge Type' = 'Hedging Type'.'Individual Volumes',
        With(
            {
                recFilteredIndividualVolume: Filter(
                    RevenueIndividualHedgeVolumes,
                    RevenueContract.'Project Revenue' = locSelectedRevenueContract.'Project Revenue'
                )
            },
            ClearCollect(
                colRevenueHedgeIndividualVolume,
                ForAll(
                    recFilteredIndividualVolume,
                    With(
                        {rec: ThisRecord},
                        {
                            IsStandardAssumption: false,
                            Year: rec.Year,
                            StartDate: rec.StartDate,
                            EndDate: rec.EndDate,
                            VolumeValue: rec.IndividualContractedmwhpa,
                            VolumeValueText: Text(rec.IndividualContractedmwhpa),
                            InitialState: false
                        }
                    )
                )
            )
        )
    ),
    "deleteRevenueContract",
    UpdateContext({locIsVisiblePopUpDeleteRevenueContract: true})
);
// Reset
Reset(drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Label_1);
Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Description_1);
