//locRevenuePriceActual

//Above locRevenuePriceActual is Changed into the below code for Calculation of tarrif price with correction factor

With(
    {
        recTarrifPrice: If(
            And(
                gblRecordSelectedProject.Country.Name = "Germany",
                drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Label_1.Selected.Value = 'Revenue Labels'.FiT,
                gblRecordSelectedProject.Technology <> Technology.PV
            ),
            Text(
                Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_BiddingPrice_1.Value) * Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_1.Value),
                "0.00"
            ),
            Not(IsBlank(locSelectedRevenueContract)),
            Text(
                locRevenuePrice.Value,
                "0.00"
            ),
            Text(
                locRevenuePrice.Value,
                "0.00"
            )
        )
    },
    recTarrifPrice
)

With(
    {
        varTariffText: Trim(Self.Text),
        varPreviousTariffText: Trim(
            Coalesce(
                locRevenuePriceActual,
                Text(
                    Value(locRevenuePrice.Value),
                    "0.00"
                )
            )
        ),
        varTariffIsValidNumber: And(
            !IsBlank(Self.Text),
            IsNumeric(Self.Text),
            Not(lbl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_TariffPrice_ErrorMessage_1.Visible)
        )
    },

    // 1. Any manual text change should immediately make tariff non-standard.
    // This handles cases like 82. also.
    If(
        And(
            Self.DisplayMode <> DisplayMode.Disabled,
            varTariffText <> varPreviousTariffText
        ),
        Concurrent(
            UpdateContext({locStandardAssumtionContract: false}),
            UpdateContext(
                {
                    locRevenuePrice: {
                        Value: locRevenuePrice.Value,
                        IsStandardAssumption: false,
                        StandardAssumptionValue: locRevenuePrice.StandardAssumptionValue
                    }
                }
            )
        )
    );

    // 2. Only update actual numeric value when the input is valid.
    If(
        And(
            varTariffIsValidNumber,
            varTariffText <> varPreviousTariffText
        ),
        With(
            {
                recTarrifPrice: If(
                    And(
                        gblRecordSelectedProject.Country.Name = "Germany",
                        drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Label_1.Selected.Value = 'Revenue Labels'.FiT,
                        gblRecordSelectedProject.Technology <> Technology.PV
                    ),
                    Text(
                        Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_BiddingPrice_1.Value) *
                        Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_1.Value),
                        "0.00"
                    ),
                    Text(
                        Value(Self.Text),
                        "0.00"
                    )
                ),
                recActualValue: Value(Self.Text),
                recTarrifPriceStandardAssumptionValue: Value(locRevenuePrice.StandardAssumptionValue)
            },
            UpdateContext(
                {
                    locRevenuePrice: {
                        Value: recActualValue,
                        IsStandardAssumption: false,
                        StandardAssumptionValue: recTarrifPriceStandardAssumptionValue
                    }
                }
            );
            UpdateContext(
                {
                    locRevenuePriceActual: recTarrifPrice
                }
            )
        )
    );

    UpdateContext({locRevenueContractFormDirty: true})
)

