Rules.InvariantScript:
With(
    {
        _NegativePriceAssumption: Filter(
            locCountryRelatedAssumptions,
            And(
                country = gblRecordSelectedProject.Country.Name,
                valuetype in [
                    "consider_negtive_prices_active",
                    "initial_state_toggle",
                    "standard_sync"
                ]
            )
        ),
        _RevenueTypeText: Switch(
            drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Label_1.Selected.Value,
            'Revenue Labels'.FiT,
            "FiT",
            'Revenue Labels'.PPA,
            "PPA"
        )
    },
    With(
        {
            _StandardSyncRecord: LookUp(
                _NegativePriceAssumption,
                valuetype = "standard_sync" && category = _RevenueTypeText
            ),
            _NegativePriceRecord: LookUp(
                _NegativePriceAssumption,
                valuetype = "consider_negtive_prices_active" && category = _RevenueTypeText
            ),
            _InitialStateRecord: LookUp(
                _NegativePriceAssumption,
                valuetype = "initial_state_toggle" && category = _RevenueTypeText
            ),
            _NegativePriceProductionExist: !IsEmpty(
                Filter(
                    'Energy Yields',
                    And(
                        Project.Project = gblRecordSelectedProject.Project,
                        'Consider Negative Prices' = 'Consider Negative Prices (Energy Yields)'.Yes,
                        Status = 'Status (Energy Yields)'.Active
                    )
                )
            )
        },
        With(
            {
                _StandardSync: Switch(
                    gblRecordSelectedProject.Technology,
                    Technology.Wind,
                    _StandardSyncRecord.wind = "true",
                    Technology.PV,
                    _StandardSyncRecord.pv = "true",
                    false
                ),
                _NegativePriceDisplayMode: Switch(
                    gblRecordSelectedProject.Technology,
                    Technology.Wind,
                    _NegativePriceRecord.wind = "true",
                    Technology.PV,
                    _NegativePriceRecord.pv = "true",
                    false
                ),
                _InitialState: Switch(
                    gblRecordSelectedProject.Technology,
                    Technology.Wind,
                    _InitialStateRecord.wind = "On",
                    Technology.PV,
                    _InitialStateRecord.pv = "On",
                    false
                )
            },
            UpdateContext(
                {
                    locRevenueContractConsiderNegativePrice: {
                        DisplayMode: If(
                            _NegativePriceDisplayMode,
                            DisplayMode.Edit,
                            DisplayMode.Disabled
                        ),
                        ToggleState: If(
                            _StandardSync,
                            _NegativePriceProductionExist,
                            _InitialState
                        ),
                        ManualOverride: false
                    }
                }
            )
        )
    )
);

