        recInitialState: locRevenueContractHedgeFixedValue.InitialState = false
    },
    If(
        recInitialState,
        If(
            IsBlank(recInputValue),
            "Number with no decimals",
            If(
                recInputValue > recProjectTotalYield,
                "The Hedged Volume may not exceed the project's Net Yield p50",
                Blank()
            )
        )
    )
)

