        recSelfText: Trim(Self.Text),
        recIsWholeNumber: IsMatch(
            Trim(Self.Text),
            "^[0-9]+$"
        ),
        recNumValue: If(
            IsMatch(
                Trim(Self.Text),
                "^[0-9]+$"
            ),
            Value(Trim(Self.Text)),
            Blank()
        ),
        recItem: ThisItem,
        recItemIndividualVolumeStandardAssumption: ThisItem.IsStandardAssumption
    },
    Patch(
        colRevenueHedgeIndividualVolume,
        recItem,
        {
            IsStandardAssumption: false,
            VolumeValue: recNumValue,
            VolumeValueText: If(
                recIsWholeNumber,
                Text(
