        recInputValue: If(
            IsMatch(
                Trim(txt_ProjectRevenue_RightPanel_IndividualVolume_Value.Text),
                "^[0-9]+$"
            ),
            Value(Trim(txt_ProjectRevenue_RightPanel_IndividualVolume_Value.Text)),
            Blank()
        ),
        recProjectTotalYield: Coalesce(
