UpdateContext(
    {
        locSpinnerInformationText: "Please wait, saving...",
        locIsVisiblePopUpSpinner: true
    }
);
If(
    rad_ProjectRevenue_HedgeType.Selected.Value = 'Hedging Type'.'Hedged Volume [%]',
    UpdateContext({locSpinnerInformationText: "Validating Hedged Volume..."});
    // Hedge Volume condition validation (Sum in a specific timeframe <= 100%) before saving
    ClearCollect(
        colRevenueContractHedgedVolumeValidationMonths,
        ForAll(
            Sequence(
                DateDiff(
                    dte_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractStartDate_1.SelectedDate,
                    dte_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractEndDate_1.SelectedDate,
                    TimeUnit.Months
                ) + 1
            ) As MonthNumber,
            {
                Id: MonthNumber.Value,
                Value: DateAdd(
                    dte_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractStartDate_1.SelectedDate,
                    MonthNumber.Value - 1,
                    TimeUnit.Months
                )
            }
        )
    );
    ClearCollect(
        colRevenueContractHedgedVolumeValidationMonthsResults,
        ForAll(
            colRevenueContractHedgedVolumeValidationMonths,
            {
                Id: ThisRecord.Id,
                Date: ThisRecord.Value,
                Passed: true
            }
        )
    );
    With(
        {
            varAllContractsInTimeframe: Filter(
                'Project Revenues',
                And(
                    Project.Project = gblRecordSelectedProject.Project,
                    'Contract Start Date' <= dte_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractEndDate_1.SelectedDate,
                    'Contract End Date' >= dte_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractStartDate_1.SelectedDate,
                    'Project Revenue' <> locSelectedRevenueContract.'Project Revenue'
                )
            )
        },
        ForAll(
            colRevenueContractHedgedVolumeValidationMonths As MonthlyValidation,
            If(
                And(
                    Value(
                        Sum(
                            Filter(
                                varAllContractsInTimeframe,
                                And(
                                    'Contract Start Date' <= EOMonth(
                                        MonthlyValidation.Value,
                                        0
                                    ),
                                    'Contract End Date' >= Date(
                                        Year(MonthlyValidation.Value),
                                        Month(MonthlyValidation.Value),
                                        1
                                    )
                                )
                            ),
                            'Hedged Volume'
                        )
                    ) + Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_HedgedVolume_1.Value) > 100,
                    rad_ProjectRevenue_HedgeType.Selected.Value = 'Hedging Type'.'Hedged Volume [%]'
                ),
            // If condition not met, save negative result to collection
                UpdateIf(
                    colRevenueContractHedgedVolumeValidationMonthsResults,
                    Id = MonthlyValidation.Id,
                    {Passed: false}
                )
            )
        )
    ),
    1
);
If(
    IsBlank(
        LookUp(
            colRevenueContractHedgedVolumeValidationMonthsResults,
            Passed = false
        )
    ),
    // Validation condition met    
    UpdateContext(
        {
            locSpinnerInformationText: "Please wait, saving...",
            locIsVisibleRightPanelNewEditRevenueContract: false
        }
    );
    IfError(
        // Upsert Revenue Contract
        With(
            {
                varCurrentRevenueContract: Patch(
                    'Project Revenues',
                    If(
                        IsBlank(locSelectedRevenueContract),
                        Defaults('Project Revenues'),
                        LookUp(
                            'Project Revenues',
                            'Project Revenue' = locSelectedRevenueContract.'Project Revenue'
                        )
                    ),
                    {
                        Name: gblRecordSelectedProject.'Project Name' & "-" & drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Label_1.Selected.Value & "-" & txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Description_1.Value,
                        Project: gblRecordSelectedProject,
                        Subaccount: locSelectedRevenueSubaccount,
                        Label: drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Label_1.Selected.Value,
                        Description: txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Description_1.Value,
                        Currency: drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Currency_1.Selected,
                        'Bidding Price': If(
                            con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_BiddingPrice_1.Visible,
                            Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_BiddingPrice_1.Value),
                            0
                        ),
                        'Site Quality': If(
                            con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_SiteQuality_1.Visible,
                            Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_SiteQuality_1.Value),
                            0
                        ),
                        'Site Quality p90': If(
                            con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_SiteQuality_p90.Visible,
                            Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_SiteQuality_p90.Value),
                            0
                        ),
                        'Correction Factor': If(
                            con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_1.Visible,
                            Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_1.Value),
                            0
                        ),
                        'Correction Factor p90': If(
                            con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_p90.Visible,
                            Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_p90.Value),
                            0
                        ),
                        'Tariff / Price': Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_TariffPrice_1.Text),
                        'Tariff / Price p90': Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_TariffPrice_p90.Value),
                        'Contract Start Date': dte_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractStartDate_1.SelectedDate,
                        'Contract Duration Years': drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractDuration_Years_1.Selected.Value,
                        'Contract Duration Months': drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractDuration_Months_1.Selected.Value,
                        'Contract End Date': dte_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractEndDate_1.SelectedDate,
                        'Use Inflation Profile': tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationProfile_1.Checked,
                        'Inflation Start Year': If(
                            tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationProfile_1.Checked,
                            Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationStartYear_1.Value),
                            0
                        ),
                        'Use Country Inflation Profile': If(
                            tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationProfile_1.Checked,
                            tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CountryInflationProfile_1.Checked,
                            false
                        ),
                        'Inflation Country Area': gblRecordSelectedProject.'Area/State/Province'.Name,
                        /*If(
                            And(
                                tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationProfile_1.Checked,
                                con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_AreaInflationProfile_3.Visible
                            ),
                            drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_AreaInflationProfile_3.Selected.Value,
                            ""
                        )*/
                        'Inflation Profile': If(
                            tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationProfile_1.Checked,
                            Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationProfile_1.Value),
                            0
                        ),
                        'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)',
                        'Is Bidding Price Standard Assumption?': If(
                            And(
                                con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_BiddingPrice_1.Visible,
                                locRevenueIsStandardAssumptions.IsBiddingPrice
                            ),
                            true,
                            false
                        ),
                        'Is Contract Duration Years Standard Assumption?': If(
                            And(locRevenueContractDurationInYears.IsStandardAssumption),
                            true,
                            false
                        ),
                        'Is Contract Duration Months Standard Assumption?': If(
                            And(locRevenueContractDurationInMonths.IsStandardAssumption),
                            true,
                            false
                        ),
                        'Is Contract Start Date Standard Assumption?': If(
                            And(locRevenueContractStartDate.IsStandardAssumption),
                            true,
                            false
                        ),
                        'Is Contract End Date Standard Assumption?': If(
                            And(locRevenueContractEndDate.IsStandardAssumption),
                            true,
                            false
                        ),
                        'Is Tarrif / Price Standard Assumption?': If(
                            con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_BiddingPrice_1.Visible,
                            And(
                                locRevenuePrice.IsStandardAssumption,
                                locRevenueCorrectionFactorP50.IsStandardAssumption
                            ),
                            locRevenuePrice.IsStandardAssumption
                        ),
                        'Is Tarrif / Price P90 Standard Assumption?': If(
                            con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_BiddingPrice_1.Visible,
                            And(
                                locRevenuePriceP90.IsStandardAssumption,
                                locRevenueCorrectionFactorP90.IsStandardAssumption
                            ),
                            locRevenuePriceP90.IsStandardAssumption
                        ),
                        'Is Use Inflation Profile Standard Assumption?': If(
                            And(
                                tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationProfile_1.Visible,
                                locRevenueInflationProfile.IsStandardAssumption
                            ),
                            true,
                            false
                        ),
                        'Is Use Custom Inflation Standard Assumption?': If(
                            And(
                                tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CountryInflationProfile_1.Visible,
                                locRevenueInflationCountryProfile.StandardAssumptionValue
                            ),
                            true,
                            false
                        ),
                        'Is Inflation Profile Year Standard Assumption?': If(
                            And(locRevenueIsStandardAssumptions.IsInflationStartYear),
                            true,
                            false
                        ),
                        'Is Custom Inflation Profile Standard Assumption?': If(
                            And(
                                locRevenueIsStandardAssumptions.IsInflationValue,
                                con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationProfile_1.Visible
                            ),
                            true,
                            false
                        ),
                        'Is Hedged Volume Standard Assumption?': If(
                            And(
                                locRevenueIsStandardAssumptions.IsHedgedVolume,
                                rad_ProjectRevenue_HedgeType.Selected.Value = 'Hedging Type'.'Hedged Volume [%]'
                            ),
                            true,
                            false
                        ),
                        'Is Correction Factor Standard Assumption': If(
                            And(
                                con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_1.Visible,
                                locRevenueIsStandardAssumptions.IsCorrectionp50
                            ),
                            true,
                            false
                        ),
                        'Is Correction Factor P90 Standard Assumption': If(
                            And(
                                con_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_p90.Visible,
                                locRevenueIsStandardAssumptions.IsCorrectionp90
                            ),
                            true,
                            false
                        ),
                        'Consider Negative Prices': tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Consider_Negative_prices.Checked,
                        NegativePriceManualOverride: If(
                            locNegativePriceManualOverride = true,
                            'NegativePriceManualOverride (Project Revenues)'.Yes,
                            'NegativePriceManualOverride (Project Revenues)'.No
                        ),
                        'Hedge Type': rad_ProjectRevenue_HedgeType.Selected.Value,
                        'Hedged Volume': If(
                            And(rad_ProjectRevenue_HedgeType.Selected.Value = 'Hedging Type'.'Hedged Volume [%]'),
                            Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_HedgedVolume_1.Value),
                            0
                        ),
                        FixedContractedmwhpa: If(
                            And(rad_ProjectRevenue_HedgeType.Selected.Value = 'Hedging Type'.'Fixed Volume p.a. [MWh]'),
                            Value(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_FixedVolume.Text),
                            Blank()
                        )
                    }
                )
            },
            // Refresh data
            If(
                IsBlank(locSelectedRevenueContract),
                Collect(
                    colProjectRevenueContracts,
                    AddColumns(
                        varCurrentRevenueContract,
                        IsFolded,
                        false
                    )
                ),
                UpdateIf(
                    colProjectRevenueContracts,
                    'Project Revenue' = varCurrentRevenueContract.'Project Revenue',
                    AddColumns(
                        varCurrentRevenueContract,
                        IsFolded,
                        false
                    )
                )
            );
            UpdateContext(
                {
                    locSelectedRevenueContract: LookUp(
                        colProjectRevenueContracts,
                        'Project Revenue' = varCurrentRevenueContract.'Project Revenue'
                    )
                }
            );
            RemoveIf(
                RevenueIndividualHedgeVolumes,
                RevenueContract.'Project Revenue' = locSelectedRevenueContract.'Project Revenue'
            );
            If(
                rad_ProjectRevenue_HedgeType.Selected.Value = 'Hedging Type'.'Individual Volumes',
                ForAll(
                    colRevenueHedgeIndividualVolume,
                    With(
                        {
                            rec: ThisRecord,
                            recRevenueContract: LookUp(
                                'Project Revenues',
                                'Project Revenue' = locSelectedRevenueContract.'Project Revenue'
                            )
                        },
                        Patch(
                            RevenueIndividualHedgeVolumes,
                            Defaults(RevenueIndividualHedgeVolumes),
                            {
                                Year: rec.Year,
                                RevenueContract: recRevenueContract,
                                StartDate: rec.StartDate,
                                EndDate: rec.EndDate,
                                'Owning Business Unit': gblRecordSelectedProject.'Besitzer (Unternehmenseinheit)',
                                IndividualContractedmwhpa: rec.VolumeValue
                            }
                        )
                    )
                )
            );
        ),
        Notify(
            "Error: Contract could not be saved correctly. " & "Internal error: originated on " & FirstError.Source & ". Message: " & FirstError.Message & FirstError.Details.HttpResponse,
            NotificationType.Error
        )
    );
    Clear(colRevenueHedgeIndividualVolume);
    Reset(drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Label_1);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Description_1);
    Reset(drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_Currency_1);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_TariffPrice_1);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_TariffPrice_p90);
    Reset(dte_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractStartDate_1);
    Reset(drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractDuration_Years_1);
    Reset(drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractDuration_Months_1);
    Reset(dte_ProjectRevenues_RightPanel_NewEditCost_BodyContent_ContractEndDate_1);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_HedgedVolume_1);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_BiddingPrice_1);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_SiteQuality_1);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_SiteQuality_p90);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_1);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CorrectionFactor_p90);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationStartYear_1);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_InflationProfile_1);
    Reset(tgl_ProjectRevenues_RightPanel_NewEditCost_BodyContent_CountryInflationProfile_1);
    Reset(drp_ProjectRevenues_RightPanel_NewEditCost_BodyContent_AreaInflationProfile_3);
    Reset(txt_ProjectRevenues_RightPanel_NewEditCost_BodyContent_FixedVolume);
    Reset(rad_ProjectRevenue_HedgeType);
    Concurrent(
        UpdateContext({locStandardAssumtionContract: false}),
        UpdateContext({locRevenueDescription: Blank()}),
        UpdateContext({locRevenueCurrency: Blank()}),
        UpdateContext({locRevenueContractStartDate: Blank()}),
        UpdateContext({locRevenueContractHedgeVolumne: Blank()}),
        UpdateContext({locRevenueContractDurationInYears: Blank()}),
        UpdateContext({locRevenueContractDurationInMonths: Blank()}),
        UpdateContext({locRevenuePrice: Blank()}),
        UpdateContext({locRevenuePriceP90: Blank()}),
        UpdateContext({locRevenueCorrectionFactorP50: Blank()}),
        UpdateContext({locRevenueCorrectionFactorP90: Blank()}),
        UpdateContext({locRevenueInflationProfile: Blank()}),
        UpdateContext({locRevenueInflationCountryProfile: Blank()}),
        UpdateContext({locRevenueInflationCustomValue: Blank()}),
        UpdateContext({locRevenueInflationStartYear: Blank()}),
        UpdateContext({locRevenueContractEndDate: Blank()}),
        UpdateContext({locRevenuePriceActual: Blank()});
        UpdateContext({locRevenueStandardValues: Blank()});
        UpdateContext({locRevenueIsStandardAssumptions: Blank()}),
        UpdateContext({locNegativePriceManualOverride: false}),
        UpdateContext({locRevenueContractHedgeType: Blank()}),
        UpdateContext({locRevenueContractHedgeFixedValue: Blank()})
    );
    UpdateContext(
        {
            locSpinnerInformationText: "",
            locIsVisiblePopUpSpinner: false
        }
    ),
    // ELSE
    UpdateContext(
        {
            locPopUpInformationTextHedgedVolume: With(
                {
                    varSortedResults: Sort(
                        Filter(
                            colRevenueContractHedgedVolumeValidationMonthsResults,
                            Passed = false
                        ),
                        Date,
                        SortOrder.Ascending
                    )
                },
                "Hedged Volume exceeds 100% in total in a specific timeframe." & Char(10) & "From  " & Text(
                    First(varSortedResults).Date,
                    "mm.yyyy"
                ) & "  to  " & Text(
                    Last(varSortedResults).Date,
                    "mm.yyyy"
                ) & "."
            ),
            locIsVisiblePopUpInformationHedgedVolume: true,
            locIsVisiblePopUpSpinner: false,
            locSpinnerInformationText: ""
        }
    )
)

